#!/usr/bin/env bash
# Generated by orca-setup from .orca-setup.json; change that file or the kit, not this one.
# The architect's wait for a running plan. Every turn of the architect re-reads its whole context,
# so an empty wake is the most expensive thing in a run: this script waits for it, and returns
# only when there is something to do or before the prompt cache (one hour) runs out.
# Usage: ./scripts/orca/wait.sh <NNN-slug> [--ack <deliveryId>]
# The first line says why it returned:
#   WAIT MESSAGES   a batch arrived; the check JSON follows. Process every message, then wait with --ack.
#   WAIT ATTENTION  orca-watch.sh printed ATTENTION lines; its snapshot follows.
#   WAIT WORKERS    three empty checks in a row and a worker needs action; the rows follow.
#   WAIT QUIET      nothing in 50 minutes; the watch snapshot follows. Run the script again.
#   WAIT ERROR      an orca call failed; its output follows.
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 1
slug=${1:?usage: wait.sh <NNN-slug> [--ack <deliveryId>]}
ack=()
[ "${2:-}" = "--ack" ] && ack=(--ack "${3:?--ack needs a deliveryId}")
checks=5          # 5 x 10 minutes stays inside the one-hour cache
empty=0

for _ in $(seq "$checks"); do
  # Keepalive lines go to stderr; only the JSON on stdout is read.
  out=$(orca orchestration check ${ack[@]+"${ack[@]}"} --wait --types "worker_done,escalation,question" \
    --timeout-ms 600000 --json 2>/dev/null)
  ack=()
  count=$(python3 -c '
import json, sys
try:
    data = json.loads(sys.argv[1])
except ValueError:
    print("error"); sys.exit()
print(len(data.get("result", {}).get("messages", [])) if data.get("ok") else "error")
' "$out")
  if [ "$count" = "error" ]; then
    echo "WAIT ERROR orca orchestration check"
    echo "$out"
    exit 1
  fi
  if [ "$count" -gt 0 ]; then
    echo "WAIT MESSAGES $count"
    echo "$out"
    exit 0
  fi
  empty=$((empty + 1))

  watch=$(./scripts/orca/orca-watch.sh "$slug")
  if [ $? -eq 3 ]; then
    echo "WAIT ATTENTION"
    echo "$watch"
    exit 3
  fi

  if [ "$empty" -eq 3 ]; then
    # Acting rows only: `unverifiable` liveness is absence of news, never a reason to act.
    rows=$(orca orchestration worker-list --json 2>/dev/null | python3 -c '
import json, sys
try:
    workers = json.load(sys.stdin).get("result", {}).get("workers", [])
except ValueError:
    print("worker-list returned no JSON"); sys.exit()
for w in workers:
    p = w.get("projection") or {}
    attention = p.get("attention") or {}
    liveness = (p.get("liveness") or {}).get("verdict")
    if attention.get("requiresAction") or liveness == "exited" and w.get("dispatchStatus") not in ("completed", "failed"):
        print(w.get("dispatchId"), w.get("workerState"), "liveness", liveness,
              "next", json.dumps(p.get("nextAction")))
')
    if [ -n "$rows" ]; then
      echo "WAIT WORKERS"
      echo "$rows"
      exit 4
    fi
  fi
done

echo "WAIT QUIET $((checks * 10)) min"
echo "$watch"
exit 5
